INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13244, 'koKR', 'Timear widzi w twojej przyszłości Tytanowych Awangardzistów!', 'Całe Azeroth jest w niebezpieczeństwie. Szalony bóg Loken ma moc, by położyć wszystkiemu kres!$B$BW Ziemskiej Strażnicy w Salach Błyskawic tytanowi awangardziści czekają w gotowości, by wykonać straszliwą wolę Lokena na niezliczonych, niczego nieświadomych ofiarach.$B$BPrzyszłość mi się objawiła, $N. To ty masz sprawić, by do tego nie doszło!', 'Arcymag Timear w Dalaranie przewidział, że musisz zabić 7 tytanowych awangardzistów.', '', 'Wróć do arcymaga Timeara w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13253, 'koKR', 'Dowód zgonu: Loken', 'W Salach Błyskawic Loken szykuje się, by położyć kres naszemu światu. Czy muszę mówić coś więcej, $N?$B$BSiedzi tam i słucha szalonych szeptów Przedwiecznego uwięzionego pod Północną Granią. Ty i twoi przyjaciele musicie natychmiast udać się na Burzowe Szczyty!$B$BStań do walki z Lokenem w Ziemskiej Strażnicy i powstrzymaj go, zanim będzie za późno! Przynieś mi jego rubinowy pierścień, abym wiedział, że znów jesteśmy bezpieczni.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z pierścieniem z niebiańskim rubinem.$B$BTo zadanie można ukończyć tylko na poziomie heroicznym.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13244, 'koKR', 'Wszyscy jesteśmy twoimi dłużnikami, $N.$b$bJeśli cokolwiek jest pewne, to to, że nas nie $gzawiodłeś:zawiodłaś; i nie zawiedziesz w przyszłości!', 0),
(13253, 'koKR', '<Arcymag Lan\'dalock wzdycha z ulgą.>$b$bSzczerze mówiąc, obawiałem się najgorszego. Trudno stać bezczynnie, gdy inni, tacy jak ty, mierzą się ze sprawami życia i śmierci, które – jak się zdaje – codziennie zagrażają naszemu światu.$b$bCo my teraz zrobimy z tym gigantycznym pierścieniem?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13244, 'koKR', 'Nawet ja nie potrafię dociec, czemu stoimy tu i rozmawiamy, skoro jeszcze nie $gzażegnałeś:zażegnałaś; zagrożenia ze strony tytanowych awangardzistów.', 0),
(13253, 'koKR', 'Znowu rozmawiamy, $n. Czy to znaczy, że jesteśmy bezpieczni przed szaleństwem Lokena, czy też czeka nas zguba?', 0);
