INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29832, 'koKR', '%s przyjmuje Postawę bojową!', '', 0),
(29833, 'koKR', '%s przyjmuje Postawę berserkera!', '', 0),
(29834, 'koKR', '%s przyjmuje Postawę defensywną!', '', 0),
(29865, 'koKR', '%s zaczyna rzucać Rozbłysk błyskawic!', '', 0),
(30528, 'koKR', 'Chcecie stanąć przed panem? Najpierw musicie przetrwać burzę!', '', 0),
(30529, 'koKR', 'Najmniejsza iskra będzie waszą zgubą.', '', 0),
(30530, 'koKR', 'Nikt nie jest bezpieczny!', '', 0),
(30531, 'koKR', 'Porażające, wiem.', '', 0),
(30532, 'koKR', 'Porywacie się na niemożliwe.', '', 0),
(30533, 'koKR', 'Wasza iskra życia... zgasła.', '', 0),
(30534, 'koKR', 'Panie... masz gości.', '', 0),
(30535, 'koKR', 'Jaka nadzieja wam pozostała? Żadna!', '', 0),
(30536, 'koKR', 'Byłem świadkiem powstania i upadku imperiów... narodzin i wymarcia całych gatunków... Przez niezliczone tysiąclecia jedyną stałą pozostawała głupota śmiertelników. Wasza obecność tutaj to potwierdza.', '', 0),
(30537, 'koKR', 'Mój pan ukazał mi przyszłość i nie ma w niej dla was miejsca. Azeroth odrodzi się w ciemności. Yogg-Saron zostanie uwolniony! Panteon upadnie!', '', 0),
(30538, 'koKR', 'Nie ukryjecie się przed przeznaczeniem!', '', 0),
(30539, 'koKR', 'Podejdźcie bliżej. Zrobię to szybko.', '', 0),
(30540, 'koKR', 'Wasze ciało nie wytrzyma długo.', '', 0),
(30541, 'koKR', 'Tylko śmiertelnik...', '', 0),
(30542, 'koKR', 'Ja... jestem... WIECZNY!', '', 0),
(30543, 'koKR', 'Zmarnowaliście tę odrobinę czasu, jaką mieliście!', '', 0),
(30544, 'koKR', 'Moja śmierć... zwiastuje koniec tego świata.', '', 0),
(30545, 'koKR', 'Wpatrujecie się ślepo w otchłań!', '', 0),
(30546, 'koKR', 'Wasza ignorancja jest bezdenna. Czy nie widzicie, dokąd prowadzi ta ścieżka?', '', 0),
(30547, 'koKR', 'Stoicie na krawędzi zapomnienia!', '', 0),
(31407, 'koKR', 'Jestem największym z synów mego ojca! Nadszedł wasz koniec!', '', 0),
(31408, 'koKR', 'Pokażcie, na co was stać!', '', 0),
(31409, 'koKR', 'Brońcie się, choć na niewiele wam się to zda!', '', 0),
(31410, 'koKR', 'GRAAAAAH! Ujrzyjcie furię żelaza i stali!', '', 0),
(31411, 'koKR', 'Tak kończy się wasza klątwa.', '', 0),
(31412, 'koKR', 'Ciało... jest... słabe!', '', 0),
(31414, 'koKR', 'Jak to możliwe...? Ciało nie jest... silniejsze!', '', 0);
